use std::collections::HashMap;

fn two_sum(nums: &Vec<i32>, target: i32) -> Vec<usize> {
    let mut indices: HashMap<i32, usize> = HashMap::new();
    for (i, &num) in nums.iter().enumerate() {
        let complement = target - num;
        if let Some(&j) = indices.get(&complement) {
            // j < i because we only insert previous elements into the map
            return vec![j, i];
        }
        indices.insert(num, i);
    }
    // The problem guarantees exactly one solution, so we should never reach here.
    unreachable!("No two-sum solution found");
}

